        if (rawFile.exists()) {
            // Try to read the file
            try {
                // Open the file for reading
                FileInputStream fis = new FileInputStream(rawFile);
                ObjectInputStream ois = new ObjectInputStream(fis);

                // Read all records from the file
                while (true) {
